/**
*@fileaudiotranscodingtoMPEG/AACAPIusageexample
*@exampletranscode_aac.c
*
*ConvertaninputaudiofiletoAACinanMP4container.Formatsotherthan
*MP4aresupportedbasedontheoutputfileextension.
*@authorAndreasUnterweger(dustsigns@gmail.com)
*/

#include<stdio.h>

#include<libavutil/mem.h>
#include<libavformat/avformat.h>
#include<libavformat/avio.h>

#include<libavcodec/avcodec.h>

#include<libavutil/audio_fifo.h>
#include<libavutil/avassert.h>
#include<libavutil/avstring.h>
#include<libavutil/channel_layout.h>
#include<libavutil/frame.h>
#include<libavutil/opt.h>

#include<libswresample/swresample.h>

/*Theoutputbitrateinbit/s*/
#defineOUTPUT_BIT_RATE96000
/*Thenumberofoutputchannels*/
#defineOUTPUT_CHANNELS2

/**
*Openaninputfileandtherequireddecoder.
*@paramfilenameFiletobeopened
*@param[out]input_format_contextFormatcontextofopenedfile
*@param[out]input_codec_contextCodeccontextofopenedfile
*@returnErrorcode(0ifsuccessful)
*/
staticintopen_input_file(constchar*filename,
AVFormatContext**input_format_context,
AVCodecContext**input_codec_context)
{
AVCodecContext*avctx;
constAVCodec*input_codec;
constAVStream*stream;
interror;

/*Opentheinputfiletoreadfromit.*/
if((error=avformat_open_input(input_format_context,filename,NULL,
NULL))<0){
fprintf(stderr,"Couldnotopeninputfile'%s'(error'%s')\n",
filename,av_err2str(error));
*input_format_context=NULL;
returnerror;
}

/*Getinformationontheinputfile(numberofstreamsetc.).*/
if((error=avformat_find_stream_info(*input_format_context,NULL))<0){
fprintf(stderr,"Couldnotopenfindstreaminfo(error'%s')\n",
av_err2str(error));
avformat_close_input(input_format_context);
returnerror;
}

/*Makesurethatthereisonlyonestreamintheinputfile.*/
if((*input_format_context)->nb_streams!=1){
fprintf(stderr,"Expectedoneaudioinputstream,butfound%d\n",
(*input_format_context)->nb_streams);
avformat_close_input(input_format_context);
returnAVERROR_EXIT;
}

stream=(*input_format_context)->streams[0];

/*Findadecoderfortheaudiostream.*/
if(!(input_codec=avcodec_find_decoder(stream->codecpar->codec_id))){
fprintf(stderr,"Couldnotfindinputcodec\n");
avformat_close_input(input_format_context);
returnAVERROR_EXIT;
}

/*Allocateanewdecodingcontext.*/
avctx=avcodec_alloc_context3(input_codec);
if(!avctx){
fprintf(stderr,"Couldnotallocateadecodingcontext\n");
avformat_close_input(input_format_context);
returnAVERROR(ENOMEM);
}

/*Initializethestreamparameterswithdemuxerinformation.*/
error=avcodec_parameters_to_context(avctx,stream->codecpar);
if(error<0){
avformat_close_input(input_format_context);
avcodec_free_context(&avctx);
returnerror;
}

/*Openthedecoderfortheaudiostreamtouseitlater.*/
if((error=avcodec_open2(avctx,input_codec,NULL))<0){
fprintf(stderr,"Couldnotopeninputcodec(error'%s')\n",
av_err2str(error));
avcodec_free_context(&avctx);
avformat_close_input(input_format_context);
returnerror;
}

/*Setthepackettimebaseforthedecoder.*/
avctx->pkt_timebase=stream->time_base;

/*Savethedecodercontextforeasieraccesslater.*/
*input_codec_context=avctx;

return0;
}

/**
*Openanoutputfileandtherequiredencoder.
*Alsosetsomebasicencoderparameters.
*Someoftheseparametersarebasedontheinputfile'sparameters.
*@paramfilenameFiletobeopened
*@paraminput_codec_contextCodeccontextofinputfile
*@param[out]output_format_contextFormatcontextofoutputfile
*@param[out]output_codec_contextCodeccontextofoutputfile
*@returnErrorcode(0ifsuccessful)
*/
staticintopen_output_file(constchar*filename,
AVCodecContext*input_codec_context,
AVFormatContext**output_format_context,
AVCodecContext**output_codec_context)
{
AVCodecContext*avctx=NULL;
AVIOContext*output_io_context=NULL;
AVStream*stream=NULL;
constAVCodec*output_codec=NULL;
interror;

/*Opentheoutputfiletowritetoit.*/
if((error=avio_open(&output_io_context,filename,
AVIO_FLAG_WRITE))<0){
fprintf(stderr,"Couldnotopenoutputfile'%s'(error'%s')\n",
filename,av_err2str(error));
returnerror;
}

/*Createanewformatcontextfortheoutputcontainerformat.*/
if(!(*output_format_context=avformat_alloc_context())){
fprintf(stderr,"Couldnotallocateoutputformatcontext\n");
returnAVERROR(ENOMEM);
}

/*Associatetheoutputfile(pointer)withthecontainerformatcontext.*/
(*output_format_context)->pb=output_io_context;

/*Guessthedesiredcontainerformatbasedonthefileextension.*/
if(!((*output_format_context)->oformat=av_guess_format(NULL,filename,
NULL))){
fprintf(stderr,"Couldnotfindoutputfileformat\n");
gotocleanup;
}

if(!((*output_format_context)->url=av_strdup(filename))){
fprintf(stderr,"Couldnotallocateurl.\n");
error=AVERROR(ENOMEM);
gotocleanup;
}

/*Findtheencodertobeusedbyitsname.*/
if(!(output_codec=avcodec_find_encoder(AV_CODEC_ID_AAC))){
fprintf(stderr,"CouldnotfindanAACencoder.\n");
gotocleanup;
}

/*Createanewaudiostreamintheoutputfilecontainer.*/
if(!(stream=avformat_new_stream(*output_format_context,NULL))){
fprintf(stderr,"Couldnotcreatenewstream\n");
error=AVERROR(ENOMEM);
gotocleanup;
}

avctx=avcodec_alloc_context3(output_codec);
if(!avctx){
fprintf(stderr,"Couldnotallocateanencodingcontext\n");
error=AVERROR(ENOMEM);
gotocleanup;
}

/*Setthebasicencoderparameters.
*Theinputfile'ssamplerateisusedtoavoidasamplerateconversion.*/
av_channel_layout_default(&avctx->ch_layout,OUTPUT_CHANNELS);
avctx->sample_rate=input_codec_context->sample_rate;
avctx->sample_fmt=output_codec->sample_fmts[0];
avctx->bit_rate=OUTPUT_BIT_RATE;

/*Setthesamplerateforthecontainer.*/
stream->time_base.den=input_codec_context->sample_rate;
stream->time_base.num=1;

/*Somecontainerformats(likeMP4)requireglobalheaderstobepresent.
*Marktheencodersothatitbehavesaccordingly.*/
if((*output_format_context)->oformat->flags&AVFMT_GLOBALHEADER)
avctx->flags|=AV_CODEC_FLAG_GLOBAL_HEADER;

/*Opentheencoderfortheaudiostreamtouseitlater.*/
if((error=avcodec_open2(avctx,output_codec,NULL))<0){
fprintf(stderr,"Couldnotopenoutputcodec(error'%s')\n",
av_err2str(error));
gotocleanup;
}

error=avcodec_parameters_from_context(stream->codecpar,avctx);
if(error<0){
fprintf(stderr,"Couldnotinitializestreamparameters\n");
gotocleanup;
}

/*Savetheencodercontextforeasieraccesslater.*/
*output_codec_context=avctx;

return0;

cleanup:
avcodec_free_context(&avctx);
avio_closep(&(*output_format_context)->pb);
avformat_free_context(*output_format_context);
*output_format_context=NULL;
returnerror<0?error:AVERROR_EXIT;
}

/**
*Initializeonedatapacketforreadingorwriting.
*@param[out]packetPackettobeinitialized
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_packet(AVPacket**packet)
{
if(!(*packet=av_packet_alloc())){
fprintf(stderr,"Couldnotallocatepacket\n");
returnAVERROR(ENOMEM);
}
return0;
}

/**
*Initializeoneaudioframeforreadingfromtheinputfile.
*@param[out]frameFrametobeinitialized
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_input_frame(AVFrame**frame)
{
if(!(*frame=av_frame_alloc())){
fprintf(stderr,"Couldnotallocateinputframe\n");
returnAVERROR(ENOMEM);
}
return0;
}

/**
*Initializetheaudioresamplerbasedontheinputandoutputcodecsettings.
*Iftheinputandoutputsampleformatsdiffer,aconversionisrequired
*libswresampletakescareofthis,butrequiresinitialization.
*@paraminput_codec_contextCodeccontextoftheinputfile
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@param[out]resample_contextResamplecontextfortherequiredconversion
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_resampler(AVCodecContext*input_codec_context,
AVCodecContext*output_codec_context,
SwrContext**resample_context)
{
interror;

/*
*Createaresamplercontextfortheconversion.
*Settheconversionparameters.
*/
error=swr_alloc_set_opts2(resample_context,
&output_codec_context->ch_layout,
output_codec_context->sample_fmt,
output_codec_context->sample_rate,
&input_codec_context->ch_layout,
input_codec_context->sample_fmt,
input_codec_context->sample_rate,
0,NULL);
if(error<0){
fprintf(stderr,"Couldnotallocateresamplecontext\n");
returnerror;
}
/*
*Performasanitychecksothatthenumberofconvertedsamplesis
*notgreaterthanthenumberofsamplestobeconverted.
*Ifthesampleratesdiffer,thiscasehastobehandleddifferently
*/
av_assert0(output_codec_context->sample_rate==input_codec_context->sample_rate);

/*Opentheresamplerwiththespecifiedparameters.*/
if((error=swr_init(*resample_context))<0){
fprintf(stderr,"Couldnotopenresamplecontext\n");
swr_free(resample_context);
returnerror;
}
return0;
}

/**
*InitializeaFIFObufferfortheaudiosamplestobeencoded.
*@param[out]fifoSamplebuffer
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_fifo(AVAudioFifo**fifo,AVCodecContext*output_codec_context)
{
/*CreatetheFIFObufferbasedonthespecifiedoutputsampleformat.*/
if(!(*fifo=av_audio_fifo_alloc(output_codec_context->sample_fmt,
output_codec_context->ch_layout.nb_channels,1))){
fprintf(stderr,"CouldnotallocateFIFO\n");
returnAVERROR(ENOMEM);
}
return0;
}

/**
*Writetheheaderoftheoutputfilecontainer.
*@paramoutput_format_contextFormatcontextoftheoutputfile
*@returnErrorcode(0ifsuccessful)
*/
staticintwrite_output_file_header(AVFormatContext*output_format_context)
{
interror;
if((error=avformat_write_header(output_format_context,NULL))<0){
fprintf(stderr,"Couldnotwriteoutputfileheader(error'%s')\n",
av_err2str(error));
returnerror;
}
return0;
}

/**
*Decodeoneaudioframefromtheinputfile.
*@paramframeAudioframetobedecoded
*@paraminput_format_contextFormatcontextoftheinputfile
*@paraminput_codec_contextCodeccontextoftheinputfile
*@param[out]data_presentIndicateswhetherdatahasbeendecoded
*@param[out]finishedIndicateswhethertheendoffilehas
*beenreachedandalldatahasbeen
*decoded.Ifthisflagisfalse,there
*ismoredatatobedecoded,i.e.,this
*functionhastobecalledagain.
*@returnErrorcode(0ifsuccessful)
*/
staticintdecode_audio_frame(AVFrame*frame,
AVFormatContext*input_format_context,
AVCodecContext*input_codec_context,
int*data_present,int*finished)
{
/*Packetusedfortemporarystorage.*/
AVPacket*input_packet;
interror;

error=init_packet(&input_packet);
if(error<0)
returnerror;

*data_present=0;
*finished=0;
/*Readoneaudioframefromtheinputfileintoatemporarypacket.*/
if((error=av_read_frame(input_format_context,input_packet))<0){
/*Ifweareattheendofthefile,flushthedecoderbelow.*/
if(error==AVERROR_EOF)
*finished=1;
else{
fprintf(stderr,"Couldnotreadframe(error'%s')\n",
av_err2str(error));
gotocleanup;
}
}

/*Sendtheaudioframestoredinthetemporarypackettothedecoder.
*Theinputaudiostreamdecoderisusedtodothis.*/
if((error=avcodec_send_packet(input_codec_context,input_packet))<0){
fprintf(stderr,"Couldnotsendpacketfordecoding(error'%s')\n",
av_err2str(error));
gotocleanup;
}

/*Receiveoneframefromthedecoder.*/
error=avcodec_receive_frame(input_codec_context,frame);
/*Ifthedecoderasksformoredatatobeabletodecodeaframe,
*returnindicatingthatnodataispresent.*/
if(error==AVERROR(EAGAIN)){
error=0;
gotocleanup;
/*Iftheendoftheinputfileisreached,stopdecoding.*/
}elseif(error==AVERROR_EOF){
*finished=1;
error=0;
gotocleanup;
}elseif(error<0){
fprintf(stderr,"Couldnotdecodeframe(error'%s')\n",
av_err2str(error));
gotocleanup;
/*Defaultcase:Returndecodeddata.*/
}else{
*data_present=1;
gotocleanup;
}

cleanup:
av_packet_free(&input_packet);
returnerror;
}

/**
*Initializeatemporarystorageforthespecifiednumberofaudiosamples.
*Theconversionrequirestemporarystorageduetothedifferentformat.
*Thenumberofaudiosamplestobeallocatedisspecifiedinframe_size.
*@param[out]converted_input_samplesArrayofconvertedsamples.The
*dimensionsarereference,channel
*(formulti-channelaudio),sample.
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@paramframe_sizeNumberofsamplestobeconvertedin
*eachround
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_converted_samples(uint8_t***converted_input_samples,
AVCodecContext*output_codec_context,
intframe_size)
{
interror;

/*Allocateasmanypointersasthereareaudiochannels.
*Eachpointerwillpointtotheaudiosamplesofthecorresponding
*channels(althoughitmaybeNULLforinterleavedformats).
*Allocatememoryforthesamplesofallchannelsinoneconsecutive
*blockforconvenience.*/
if((error=av_samples_alloc_array_and_samples(converted_input_samples,NULL,
output_codec_context->ch_layout.nb_channels,
frame_size,
output_codec_context->sample_fmt,0))<0){
fprintf(stderr,
"Couldnotallocateconvertedinputsamples(error'%s')\n",
av_err2str(error));
returnerror;
}
return0;
}

/**
*Converttheinputaudiosamplesintotheoutputsampleformat.
*Theconversionhappensonaper-framebasis,thesizeofwhichis
*specifiedbyframe_size.
*@paraminput_dataSamplestobedecoded.Thedimensionsare
*channel(formulti-channelaudio),sample.
*@param[out]converted_dataConvertedsamples.Thedimensionsarechannel
*(formulti-channelaudio),sample.
*@paramframe_sizeNumberofsamplestobeconverted
*@paramresample_contextResamplecontextfortheconversion
*@returnErrorcode(0ifsuccessful)
*/
staticintconvert_samples(constuint8_t**input_data,
uint8_t**converted_data,constintframe_size,
SwrContext*resample_context)
{
interror;

/*Convertthesamplesusingtheresampler.*/
if((error=swr_convert(resample_context,
converted_data,frame_size,
input_data,frame_size))<0){
fprintf(stderr,"Couldnotconvertinputsamples(error'%s')\n",
av_err2str(error));
returnerror;
}

return0;
}

/**
*AddconvertedinputaudiosamplestotheFIFObufferforlaterprocessing.
*@paramfifoBuffertoaddthesamplesto
*@paramconverted_input_samplesSamplestobeadded.Thedimensionsarechannel
*(formulti-channelaudio),sample.
*@paramframe_sizeNumberofsamplestobeconverted
*@returnErrorcode(0ifsuccessful)
*/
staticintadd_samples_to_fifo(AVAudioFifo*fifo,
uint8_t**converted_input_samples,
constintframe_size)
{
interror;

/*MaketheFIFOaslargeasitneedstobetoholdboth,
*theoldandthenewsamples.*/
if((error=av_audio_fifo_realloc(fifo,av_audio_fifo_size(fifo)+frame_size))<0){
fprintf(stderr,"CouldnotreallocateFIFO\n");
returnerror;
}

/*StorethenewsamplesintheFIFObuffer.*/
if(av_audio_fifo_write(fifo,(void**)converted_input_samples,
frame_size)<frame_size){
fprintf(stderr,"CouldnotwritedatatoFIFO\n");
returnAVERROR_EXIT;
}
return0;
}

/**
*Readoneaudioframefromtheinputfile,decode,convertandstore
*itintheFIFObuffer.
*@paramfifoBufferusedfortemporarystorage
*@paraminput_format_contextFormatcontextoftheinputfile
*@paraminput_codec_contextCodeccontextoftheinputfile
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@paramresampler_contextResamplecontextfortheconversion
*@param[out]finishedIndicateswhethertheendoffilehas
*beenreachedandalldatahasbeen
*decoded.Ifthisflagisfalse,
*thereismoredatatobedecoded,
*i.e.,thisfunctionhastobecalled
*again.
*@returnErrorcode(0ifsuccessful)
*/
staticintread_decode_convert_and_store(AVAudioFifo*fifo,
AVFormatContext*input_format_context,
AVCodecContext*input_codec_context,
AVCodecContext*output_codec_context,
SwrContext*resampler_context,
int*finished)
{
/*Temporarystorageoftheinputsamplesoftheframereadfromthefile.*/
AVFrame*input_frame=NULL;
/*Temporarystoragefortheconvertedinputsamples.*/
uint8_t**converted_input_samples=NULL;
intdata_present;
intret=AVERROR_EXIT;

/*Initializetemporarystorageforoneinputframe.*/
if(init_input_frame(&input_frame))
gotocleanup;
/*Decodeoneframeworthofaudiosamples.*/
if(decode_audio_frame(input_frame,input_format_context,
input_codec_context,&data_present,finished))
gotocleanup;
/*Ifweareattheendofthefileandtherearenomoresamples
*inthedecoderwhicharedelayed,weareactuallyfinished.
*Thismustnotbetreatedasanerror.*/
if(*finished){
ret=0;
gotocleanup;
}
/*Ifthereisdecodeddata,convertandstoreit.*/
if(data_present){
/*Initializethetemporarystoragefortheconvertedinputsamples.*/
if(init_converted_samples(&converted_input_samples,output_codec_context,
input_frame->nb_samples))
gotocleanup;

/*Converttheinputsamplestothedesiredoutputsampleformat.
*Thisrequiresatemporarystorageprovidedbyconverted_input_samples.*/
if(convert_samples((constuint8_t**)input_frame->extended_data,converted_input_samples,
input_frame->nb_samples,resampler_context))
gotocleanup;

/*AddtheconvertedinputsamplestotheFIFObufferforlaterprocessing.*/
if(add_samples_to_fifo(fifo,converted_input_samples,
input_frame->nb_samples))
gotocleanup;
ret=0;
}
ret=0;

cleanup:
if(converted_input_samples)
av_freep(&converted_input_samples[0]);
av_freep(&converted_input_samples);
av_frame_free(&input_frame);

returnret;
}

/**
*Initializeoneinputframeforwritingtotheoutputfile.
*Theframewillbeexactlyframe_sizesampleslarge.
*@param[out]frameFrametobeinitialized
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@paramframe_sizeSizeoftheframe
*@returnErrorcode(0ifsuccessful)
*/
staticintinit_output_frame(AVFrame**frame,
AVCodecContext*output_codec_context,
intframe_size)
{
interror;

/*Createanewframetostoretheaudiosamples.*/
if(!(*frame=av_frame_alloc())){
fprintf(stderr,"Couldnotallocateoutputframe\n");
returnAVERROR_EXIT;
}

/*Settheframe'sparameters,especiallyitssizeandformat.
*av_frame_get_bufferneedsthistoallocatememoryforthe
*audiosamplesoftheframe.
*Defaultchannellayoutsbasedonthenumberofchannels
*areassumedforsimplicity.*/
(*frame)->nb_samples=frame_size;
av_channel_layout_copy(&(*frame)->ch_layout,&output_codec_context->ch_layout);
(*frame)->format=output_codec_context->sample_fmt;
(*frame)->sample_rate=output_codec_context->sample_rate;

/*Allocatethesamplesofthecreatedframe.Thiscallwillmake
*surethattheaudioframecanholdasmanysamplesasspecified.*/
if((error=av_frame_get_buffer(*frame,0))<0){
fprintf(stderr,"Couldnotallocateoutputframesamples(error'%s')\n",
av_err2str(error));
av_frame_free(frame);
returnerror;
}

return0;
}

/*Globaltimestampfortheaudioframes.*/
staticint64_tpts=0;

/**
*Encodeoneframeworthofaudiototheoutputfile.
*@paramframeSamplestobeencoded
*@paramoutput_format_contextFormatcontextoftheoutputfile
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@param[out]data_presentIndicateswhetherdatahasbeen
*encoded
*@returnErrorcode(0ifsuccessful)
*/
staticintencode_audio_frame(AVFrame*frame,
AVFormatContext*output_format_context,
AVCodecContext*output_codec_context,
int*data_present)
{
/*Packetusedfortemporarystorage.*/
AVPacket*output_packet;
interror;

error=init_packet(&output_packet);
if(error<0)
returnerror;

/*Setatimestampbasedonthesamplerateforthecontainer.*/
if(frame){
frame->pts=pts;
pts+=frame->nb_samples;
}

*data_present=0;
/*Sendtheaudioframestoredinthetemporarypackettotheencoder.
*Theoutputaudiostreamencoderisusedtodothis.*/
error=avcodec_send_frame(output_codec_context,frame);
/*Checkforerrors,butproceedwithfetchingencodedsamplesifthe
*encodersignalsthatithasnothingmoretoencode.*/
if(error<0&&error!=AVERROR_EOF){
fprintf(stderr,"Couldnotsendpacketforencoding(error'%s')\n",
av_err2str(error));
gotocleanup;
}

/*Receiveoneencodedframefromtheencoder.*/
error=avcodec_receive_packet(output_codec_context,output_packet);
/*Iftheencoderasksformoredatatobeabletoprovidean
*encodedframe,returnindicatingthatnodataispresent.*/
if(error==AVERROR(EAGAIN)){
error=0;
gotocleanup;
/*Ifthelastframehasbeenencoded,stopencoding.*/
}elseif(error==AVERROR_EOF){
error=0;
gotocleanup;
}elseif(error<0){
fprintf(stderr,"Couldnotencodeframe(error'%s')\n",
av_err2str(error));
gotocleanup;
/*Defaultcase:Returnencodeddata.*/
}else{
*data_present=1;
}

/*Writeoneaudioframefromthetemporarypackettotheoutputfile.*/
if(*data_present&&
(error=av_write_frame(output_format_context,output_packet))<0){
fprintf(stderr,"Couldnotwriteframe(error'%s')\n",
av_err2str(error));
gotocleanup;
}

cleanup:
av_packet_free(&output_packet);
returnerror;
}

/**
*LoadoneaudioframefromtheFIFObuffer,encodeandwriteittothe
*outputfile.
*@paramfifoBufferusedfortemporarystorage
*@paramoutput_format_contextFormatcontextoftheoutputfile
*@paramoutput_codec_contextCodeccontextoftheoutputfile
*@returnErrorcode(0ifsuccessful)
*/
staticintload_encode_and_write(AVAudioFifo*fifo,
AVFormatContext*output_format_context,
AVCodecContext*output_codec_context)
{
/*Temporarystorageoftheoutputsamplesoftheframewrittentothefile.*/
AVFrame*output_frame;
/*Usethemaximumnumberofpossiblesamplesperframe.
*IfthereislessthanthemaximumpossibleframesizeintheFIFO
*bufferusethisnumber.Otherwise,usethemaximumpossibleframesize.*/
constintframe_size=FFMIN(av_audio_fifo_size(fifo),
output_codec_context->frame_size);
intdata_written;

/*Initializetemporarystorageforoneoutputframe.*/
if(init_output_frame(&output_frame,output_codec_context,frame_size))
returnAVERROR_EXIT;

/*ReadasmanysamplesfromtheFIFObufferasrequiredtofilltheframe.
*Thesamplesarestoredintheframetemporarily.*/
if(av_audio_fifo_read(fifo,(void**)output_frame->data,frame_size)<frame_size){
fprintf(stderr,"CouldnotreaddatafromFIFO\n");
av_frame_free(&output_frame);
returnAVERROR_EXIT;
}

/*Encodeoneframeworthofaudiosamples.*/
if(encode_audio_frame(output_frame,output_format_context,
output_codec_context,&data_written)){
av_frame_free(&output_frame);
returnAVERROR_EXIT;
}
av_frame_free(&output_frame);
return0;
}

/**
*Writethetraileroftheoutputfilecontainer.
*@paramoutput_format_contextFormatcontextoftheoutputfile
*@returnErrorcode(0ifsuccessful)
*/
staticintwrite_output_file_trailer(AVFormatContext*output_format_context)
{
interror;
if((error=av_write_trailer(output_format_context))<0){
fprintf(stderr,"Couldnotwriteoutputfiletrailer(error'%s')\n",
av_err2str(error));
returnerror;
}
return0;
}

intmain(intargc,char**argv)
{
AVFormatContext*input_format_context=NULL,*output_format_context=NULL;
AVCodecContext*input_codec_context=NULL,*output_codec_context=NULL;
SwrContext*resample_context=NULL;
AVAudioFifo*fifo=NULL;
intret=AVERROR_EXIT;

if(argc!=3){
fprintf(stderr,"Usage:%s<inputfile><outputfile>\n",argv[0]);
exit(1);
}

/*Opentheinputfileforreading.*/
if(open_input_file(argv[1],&input_format_context,
&input_codec_context))
gotocleanup;
/*Opentheoutputfileforwriting.*/
if(open_output_file(argv[2],input_codec_context,
&output_format_context,&output_codec_context))
gotocleanup;
/*Initializetheresamplertobeabletoconvertaudiosampleformats.*/
if(init_resampler(input_codec_context,output_codec_context,
&resample_context))
gotocleanup;
/*InitializetheFIFObuffertostoreaudiosamplestobeencoded.*/
if(init_fifo(&fifo,output_codec_context))
gotocleanup;
/*Writetheheaderoftheoutputfilecontainer.*/
if(write_output_file_header(output_format_context))
gotocleanup;

/*Loopaslongaswehaveinputsamplestoreadoroutputsamples
*towrite;abortassoonaswehaveneither.*/
while(1){
/*Usetheencoder'sdesiredframesizeforprocessing.*/
constintoutput_frame_size=output_codec_context->frame_size;
intfinished=0;

/*MakesurethatthereisoneframeworthofsamplesintheFIFO
*buffersothattheencodercandoitswork.
*Sincethedecoder'sandtheencoder'sframesizemaydiffer,we
*needtoFIFObuffertostoreasmanyframesworthofinputsamples
*thattheymakeupatleastoneframeworthofoutputsamples.*/
while(av_audio_fifo_size(fifo)<output_frame_size){
/*Decodeoneframeworthofaudiosamples,convertittothe
*outputsampleformatandputitintotheFIFObuffer.*/
if(read_decode_convert_and_store(fifo,input_format_context,
input_codec_context,
output_codec_context,
resample_context,&finished))
gotocleanup;

/*Ifweareattheendoftheinputfile,wecontinue
*encodingtheremainingaudiosamplestotheoutputfile.*/
if(finished)
break;
}

/*Ifwehaveenoughsamplesfortheencoder,weencodethem.
*Attheendofthefile,wepasstheremainingsamplesto
*theencoder.*/
while(av_audio_fifo_size(fifo)>=output_frame_size||
(finished&&av_audio_fifo_size(fifo)>0))
/*TakeoneframeworthofaudiosamplesfromtheFIFObuffer,
*encodeitandwriteittotheoutputfile.*/
if(load_encode_and_write(fifo,output_format_context,
output_codec_context))
gotocleanup;

/*Ifweareattheendoftheinputfileandhaveencoded
*allremainingsamples,wecanexitthisloopandfinish.*/
if(finished){
intdata_written;
/*Flushtheencoderasitmayhavedelayedframes.*/
do{
if(encode_audio_frame(NULL,output_format_context,
output_codec_context,&data_written))
gotocleanup;
}while(data_written);
break;
}
}

/*Writethetraileroftheoutputfilecontainer.*/
if(write_output_file_trailer(output_format_context))
gotocleanup;
ret=0;

cleanup:
if(fifo)
av_audio_fifo_free(fifo);
swr_free(&resample_context);
if(output_codec_context)
avcodec_free_context(&output_codec_context);
if(output_format_context){
avio_closep(&output_format_context->pb);
avformat_free_context(output_format_context);
}
if(input_codec_context)
avcodec_free_context(&input_codec_context);
if(input_format_context)
avformat_close_input(&input_format_context);

returnret;
}
